questions.solution:
\begin{block}{Calcul des premiers termes}
\begin{itemize}
  \item $u_1 = \frac{1}{2} u_0 + 3 = \frac{1}{2}(2) + 3 = 1 + 3 = 4$
  \item $u_2 = \frac{1}{2} u_1 + 3 = \frac{1}{2}(4) + 3 = 2 + 3 = 5$
  \item $u_3 = \frac{1}{2} u_2 + 3 = \frac{1}{2}(5) + 3 = 2{,}5 + 3 = 5{,}5 = \frac{11}{2}$
\end{itemize}
\end{block}

\begin{block}{Sens de variation}
Étudions le signe de $u_{n+1} - u_n$ :
$$ u_{n+1} - u_n = \left(\frac{1}{2}u_n + 3\right) - u_n = 3 - \frac{1}{2}u_n = \frac{6 - u_n}{2} $$
D'après la question précédente, $u_n < 6$ pour tout $n$, donc $6 - u_n > 0$.

Ainsi, $u_{n+1} - u_n > 0$, ce qui prouve que la suite $(u_n)$ est \textbf{strictement croissante}.
\end{block}

subquestions.solution:
\begin{block}{Nature de la suite $(v_n)$}
Pour tout $n \in \mathbb{N}$ :
$$ v_{n+1} = u_{n+1} - 6 = \left(\frac{1}{2}u_n + 3\right) - 6 = \frac{1}{2}u_n - 3 = \frac{1}{2}(u_n - 6) = \frac{1}{2} v_n $$
Donc $(v_n)$ est une suite géométrique de raison $q = \frac{1}{2}$.

Son premier terme est $v_0 = u_0 - 6 = 2 - 6 = -4$.
\end{block}

\begin{block}{Expressions explicites}
Comme $(v_n)$ est géométrique :
$$ v_n = v_0 \times q^n = -4 \times \left(\frac{1}{2}\right)^n $$
Puisque $v_n = u_n - 6$, on en déduit $u_n = v_n + 6$, soit :
$$ u_n = 6 - 4 \left(\frac{1}{2}\right)^n $$
\end{block}

\begin{block}{Calcul de la limite}
Comme $-1 < \frac{1}{2} < 1$, on a $\lim_{n \to +\infty} \left(\frac{1}{2}\right)^n = 0$.

Par conséquent :
$$ \lim_{n \to +\infty} u_n = \lim_{n \to +\infty} \left(6 - 4 \left(\frac{1}{2}\right)^n\right) = 6 - 0 = 6 $$
\end{block}

\begin{block}{Expressions explicites}
Comme $(w_n)$ est géométrique :
$$ w_n = -500 \times (0{,}9)^n $$
D'où $u_n = w_n + 1500$ :
$$ u_n = 1500 - 500 \times (0{,}9)^n $$
\end{block}

questions.solution:
\begin{block}{Limite et interprétation}
Comme $-1 < 0{,}9 < 1$, $\lim_{n \to +\infty} (0{,}9)^n = 0$.

Par conséquent :
$$ \lim_{n \to +\infty} u_n = 1500 - 500 \times 0 = 1500 $$
\textbf{Interprétation :} À long terme, la population d'individus dans la réserve naturelle va se stabiliser à $1500$ individus.
\end{block}

\begin{block}{Inégalités élémentaires}
Pour tout $1 \le k \le n$ :
$$ 1 \le k \le n \implies n^2 + 1 \le n^2 + k \le n^2 + n $$
\end{block}

\begin{block}{Théorème des gendarmes}
Les deux suites encadrantes convergent vers la même limite $1$.

D'après le \textbf{théorème des gendarmes (ou théorème d'encadrement)}, la suite $(u_n)$ converge également et :
$$ \lim_{n \to +\infty} u_n = 1 $$
\end{block}

\begin{block}{Convergence}
La suite $(u_n)$ est croissante et majorée par $2$.

D'après le \textbf{théorème de la convergence monotone}, la suite $(u_n)$ est convergente vers une limite réelle $\ell \in [0, 2]$.
\end{block}

subquestions.solution:
\begin{block}{Relation de récurrence pour $d_n$}
$$ d_{n+1} = b_{n+1} - a_{n+1} = \frac{a_n + 3b_n}{4} - \frac{a_n + 2b_n}{3} $$
Réduisons au même dénominateur $12$ :
$$ d_{n+1} = \frac{3(a_n + 3b_n) - 4(a_n + 2b_n)}{12} = \frac{3a_n + 9b_n - 4a_n - 8b_n}{12} = \frac{b_n - a_n}{12} = \frac{1}{12} d_n $$
\end{block}

\begin{block}{Suite géométrique $d_n$}
La suite $(d_n)$ est géométrique de raison $q = \frac{1}{12}$.
Son premier terme est $d_0 = b_0 - a_0 = 8 - 1 = 7$.

Ainsi, pour tout $n \in \mathbb{N}$ :
$$ d_n = 7 \left(\frac{1}{12}\right)^n $$
\end{block}

questions.solution:
\begin{block}{Sens de variation de $(a_n)$ et $(b_n)$}
\begin{itemize}
  \item $a_{n+1} - a_n = \frac{a_n + 2b_n}{3} - a_n = \frac{2(b_n - a_n)}{3} = \frac{2}{3} d_n > 0$, donc $(a_n)$ est \textbf{croissante}.
  \item $b_{n+1} - b_n = \frac{a_n + 3b_n}{4} - b_n = \frac{a_n - b_n}{4} = -\frac{1}{4} d_n < 0$, donc $(b_n)$ est \textbf{décroissante}.
\end{itemize}
\end{block}

\begin{block}{Suites adjacentes}
Les suites $(a_n)$ et $(b_n)$ vérifient :
1. $(a_n)$ est croissante ;
2. $(b_n)$ est décroissante ;
3. $\lim_{n \to +\infty} (b_n - a_n) = \lim_{n \to +\infty} d_n = 0$.

Par définition, les suites $(a_n)$ et $(b_n)$ sont \textbf{adjacentes}. Elles convergent donc toutes les deux vers une \textbf{même limite réelle} $\ell$.
\end{block}
